-- Stores the frozen A2Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a2q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A2Q';
 v_cp constant text := 'A2Q_C2';
 v_wi constant bigint := 1112;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A2Q_C2';
 v_packet_sha constant text := 'a34a7f990b9363d7c38a67eea63a9582f71d1584611d98ee3c0cc620b0b696c7';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"authority_and_implementation_state_must_be":"UNKNOWN","classification_keys":["target_granularity","change_type","depth","authority_state","implementation_state"],"depth_rule":"derive_depth monotonic precedence","forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"no_source_marker":"NO_SOURCE_SUPPLIED","request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001","signal_names":["materiality_level","scope_bounded","authority_state","reversibility_state","currentness_decision","material_contradiction","known_cross_scope_impact","unresolved_material_signal_count","required_specialist_count"]},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"La solicitud afirma que los clientes abandonan; no aporta cifras ni evidencia cuantitativa.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"Se indica urgencia, pero no una fecha o hito preciso del piloto.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n","input_origin":"A1Q_C2 GPT Native RAW (raw_output_sha256 02420a0ebbc3416193b788a95895966837db15cd2d934b7691924ade94303fce)","input_sha256":"02420a0ebbc3416193b788a95895966837db15cd2d934b7691924ade94303fce","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","classification","signals","signal_sources","depth_reason","evidence_refs"],"schema":"A2_CLASSIFICATION_OUTPUT_V1","validator":"analysis_qualification_a2q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"a34a7f990b9363d7c38a67eea63a9582f71d1584611d98ee3c0cc620b0b696c7","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A2 (clasificación) del perfil de análisis. Recibes el contexto normalizado de la etapa A1 (abajo). Clasifica el cambio. No infieras solución técnica. No inventes fuentes: las únicas fuentes válidas son las del contexto (sus source_refs, 'ambiguity:<code>' y 'fact:<fact_code>'); si una señal no tiene fuente en el contexto, su fuente es 'NO_SOURCE_SUPPLIED' y su valor debe ser UNKNOWN/UNRESOLVED. El estado de autoridad y de implementación no se pueden afirmar sin evidencia: usa UNKNOWN. Lo desconocido material nunca puede ser L1. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, classification, signals, signal_sources, depth_reason, evidence_refs. schema_version='A2_CLASSIFICATION_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. classification={target_granularity (texto), change_type (texto), depth (L1|L2|L3), authority_state (EXISTING|NEW|UNKNOWN), implementation_state (EXISTING|NEW|UNKNOWN)}. signals={materiality_level (LOW|MEDIUM|HIGH|UNKNOWN), scope_bounded (TRUE|FALSE|UNKNOWN), authority_state (SUFFICIENT|INSUFFICIENT|UNKNOWN), reversibility_state (DEMONSTRATED|NOT_DEMONSTRATED|UNKNOWN), currentness_decision (CURRENT|CURRENT_REBOUND|STALE_AFFECTED|UNKNOWN_FAIL_CLOSED|UNRESOLVED), material_contradiction (true|false), known_cross_scope_impact (true|false|\"UNKNOWN\"), unresolved_material_signal_count (entero >=0), required_specialist_count (entero >=0)}. signal_sources=lista con UN elemento por cada una de las 9 señales: {signal, source_ref}. Regla de profundidad (precedencia monótona): L3 si materiality_level=HIGH o material_contradiction=true o known_cross_scope_impact=true; L1 solo si materiality LOW, scope_bounded TRUE, authority_state SUFFICIENT, reversibility DEMONSTRATED, currentness CURRENT o CURRENT_REBOUND, known_cross_scope_impact=false y unresolved_material_signal_count=0; en otro caso L2. depth_reason: texto no vacío que justifica la profundidad. evidence_refs: lista no vacía de fuentes válidas del contexto.\n\nCONTEXTO A1 (JSON):\n{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"La solicitud afirma que los clientes abandonan; no aporta cifras ni evidencia cuantitativa.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"Se indica urgencia, pero no una fecha o hito preciso del piloto.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n","request_sha256":"ba264f710396a97ae48b345a46789df1dcb06e8180f2ac12c04d4be2eb4ebb5a","run_id":"A2Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A2","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A2Q/A2Q_C2","unit":"A2"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A2Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A2Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A2Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A2Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A2Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A2Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A2Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A2Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A2Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A2Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A2Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A2Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A2Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A2Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A2Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A2Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A2Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a2q_c2_prep$;
COMMIT;
